const env = $input.first().json;
const clientId = env.client_id;
const client = REGISTRY.clients[clientId];

if (!client) {
  return [{ json: { ...env, fatal: true, reason: 'unknown client_id: ' + clientId } }];
}
if (client.status !== 'active') {
  return [{ json: { ...env, fatal: true, reason: 'client not active: ' + clientId } }];
}
const kb = KBS[clientId];
if (!kb) {
  return [{ json: { ...env, fatal: true, reason: 'no KB loaded for ' + clientId } }];
}
return [{ json: { ...env, client, kb, capabilities: client.capabilities || {} } }];

// Idempotency. Meta redelivers webhooks and IMAP can re-serve a message
// after a reconnect. Answering twice looks broken to a buyer and writes a
// duplicate row into the commission ledger.
//
// Workflow static data keeps this credential-free. Swap for a Postgres
// lookup on provider_message_id once volume justifies it -- the unique
// index in 001-attribution-ledger.sql is already the durable backstop.
const env = $input.first().json;
if (env.fatal) return [{ json: env }];

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const key = env.provider_message_id;
const now = Date.now();
const TTL = 24 * 60 * 60 * 1000;

for (const k of Object.keys(store.seen)) {
  if (now - store.seen[k] > TTL) delete store.seen[k];
}

if (key && store.seen[key]) {
  return [{ json: { ...env, duplicate: true, reply: '', escalate: false } }];
}
if (key) store.seen[key] = now;

return [{ json: { ...env, duplicate: false } }];

// Post-generation guardrails. The model is not trusted to police itself.
const raw = $input.first().json;
const text = raw?.content?.parts?.[0]?.text
          ?? raw?.candidates?.[0]?.content?.parts?.[0]?.text
          ?? raw?.text ?? '';

const ESCALATION_LINE = "Let me get you the exact figure from the team — one moment. I'm connecting you with someone now.";

let out;
try {
  out = JSON.parse(String(text).replace(/^```json\s*/i,'').replace(/```\s*$/,'').trim());
} catch (e) {
  // Unparseable output is a failure, not a message to forward.
  return [{ json: { reply: ESCALATION_LINE, escalate: true, escalation_reason: 'model returned unparseable output', unit_interest: '', grounded_in: [], guard_triggered: 'parse_error' } }];
}

let reply    = String(out.reply || '');
let escalate = out.escalate === true;
let reason   = String(out.escalation_reason || '');
const grounded = Array.isArray(out.grounded_in) ? out.grounded_in : [];
let guard = '';

// 1. Banned-topic sweep. Catches a model that complied in tone but not substance.
const BANNED = [
  // 'appreciat' needs care: "I appreciate your question" is normal Nigerian
  // business English. Match the investment senses only.
  { re: /\b(roi|rental yield|yields?|return on investment|resale value|capital growth)\b|\bappreciation\b|\b(will|would|should|can|could|may|might)\s+appreciate\b|\bappreciate[sd]?\s+in\s+value\b/i, why: 'investment projection' },
  { re: /\b(guarantee|guaranteed|assured returns?)\b/i, why: 'guarantee language' },
  { re: /\baccount (number|details)\b|\b\d{10}\b/i, why: 'possible account number' },
  { re: /\bonly \d+ (unit|plot|left)/i, why: 'scarcity claim' }
];
for (const b of BANNED) {
  if (b.re.test(reply)) { escalate = true; guard = b.why; reply = ESCALATION_LINE; reason = reason || b.why; break; }
}

// 2. Ungrounded factual claim: money or measurements with nothing cited.
// Curly apostrophes are what models actually emit -- match both forms.
const looksFactual = /₦|\bN\d|\bnaira\b|\bsqm\b|\bbedroom\b|\bc of o\b|governor[\u2019']?s consent|\bgovernor'?s consent\b/i.test(reply);
if (!guard && looksFactual && grounded.length === 0) {
  escalate = true; guard = 'ungrounded_factual_claim'; reply = ESCALATION_LINE;
  reason = reason || 'stated a fact without citing the knowledge base';
}

// 3. Never return an empty reply.
if (!reply.trim()) { reply = ESCALATION_LINE; escalate = true; guard = guard || 'empty_reply'; }

return [{ json: { reply, escalate, escalation_reason: reason, unit_interest: String(out.unit_interest || ''), grounded_in: grounded, guard_triggered: guard, client_id: 'shalom-park' } }];

// Assemble what the channel adapter needs to act on.
const env = $input.first().json;

if (env.fatal)     return [{ json: { send: false, reason: env.reason, fatal: true } }];
if (env.duplicate) return [{ json: { send: false, reason: 'duplicate_message' } }];

const esc = env.client?.escalation || {};
const target = esc.primary || {};

return [{ json: {
  send: true,
  client_id:    env.client_id,
  channel:      env.channel,
  contact_id:   env.contact_id,
  thread_ref:   env.thread_ref,
  subject:      env.subject ? ('Re: ' + String(env.subject).replace(/^re:\s*/i,'')) : '',
  reply:        env.reply,
  escalate:     env.escalate === true,
  escalation:   env.escalate === true ? {
    to_name:   target.name || '',
    to_wa:     target.whatsapp || '',
    reason:    env.escalation_reason || '',
    unclaimed_alert_minutes: esc.unclaimed_alert_minutes || 15
  } : null,
  ledger: {
    provider_message_id: env.provider_message_id,
    contact_hash:        env.contact_hash,
    contact_e164:        env.contact_e164 || env.contact_email || env.contact_id,
    channel:             env.channel,
    unit_interest:       env.unit_interest || '',
    grounded_in:         env.grounded_in || [],
    guard_triggered:     env.guard_triggered || ''
  },
  // Add-on hooks: enabled per client in clients.json. Each is a future
  // sub-workflow call; the envelope already carries what they need.
  addons: {
    voice_note:  !!(env.capabilities?.voice_notes) && env.channel === 'whatsapp',
    booking:     !!(env.capabilities?.booking) && /inspect|visit|viewing|book/i.test(env.text || ''),
    doc_vault:   !!(env.capabilities?.document_vault) && /document|title|c of o|survey|deed/i.test(env.text || ''),
    lead_score:  !!(env.capabilities?.lead_scoring),
    followup:    !!(env.capabilities?.followup_sequences)
  }
}}];
